import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.io.ByteArrayOutputStream;
import java.util.zip.Inflater;

public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i + 1), 16));
        }
        return data;
    }

    /**
     * Αποκτήστε τα δεδομένα ρύθμισης από το αίτημα χρησιμοποιώντας το 'config' ως κλειδί. 
     * Αποσυμπιέστε τα δεδομένα μετά την αποκωδικοποίησή τους από το hex. 
     * Επιστρέψτε τα αποσυμπιεσμένα δεδομένα.
     * 
     * @param config Τα δεδομένα ρύθμισης κωδικοποιημένα σε hex. 
     * @return Το αποσυμπιεσμένο αντικείμενο.
     */
    public Object getConfig(String config) throws Exception {
        byte[] compressedData = hexStringToByteArray(config);
        byte[] decompressedData = decompress(compressedData);

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decompressedData))) {
            return ois.readObject();
        }
    }

    private byte[] decompress(byte[] data) throws Exception {
        Inflater inflater = new Inflater();
        inflater.setInput(data);
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream(data.length);
        byte[] buffer = new byte[1024];
        while (!inflater.finished()) {
            int count = inflater.inflate(buffer);
            outputStream.write(buffer, 0, count);
        }
        inflater.end();
        return outputStream.toByteArray();
    }
}
