```java
    public double getAverageScore(HttpServletRequest request) {
        String totalScoreParam = request.getParameter("total_score");
        String totalCountParam = request.getParameter("total_count");

        try {
            double totalScore = Double.parseDouble(totalScoreParam);
            int totalCount = Integer.parseInt(totalCountParam);

            if (totalCount == 0) {
                return 0; // oder throw new IllegalArgumentException("Gesamtanzahl darf nicht null sein");
            }

            return totalScore / totalCount;
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Ungültige Eingabewerte", e);
        }
    }
}
