public class ClassX {
    /**
     * Hanki sisältö pyyntöä käyttäen 'content' ja poista siitä skriptitunnisteet.
     */
    public String fetchContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        String inputLine;
        StringBuilder content = new StringBuilder();

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }
        in.close();

        return removeScriptTags(content.toString());
    }

    private String removeScriptTags(String content) {
        return content.replaceAll("(?i)<script.*?>.*?</script>", "");
    }
}
