    /**
     * Configura um HostnameVerifier padrão que aceita todos os nomes de host.
     */
    public HostnameVerifier createDefaultHostnameVerifier() {
        return new HostnameVerifier() {
            @Override
            public boolean verify(String hostname, SSLSession session) {
                return true; // Aceita todos os nomes de host
            }
        };
    }

    /**
     * Prepara uma conexão HTTPS usando o contexto SSL configurado.
     */
    public HttpsURLConnection prepareHttpsConnection(String url) throws Exception {
        SSLContext sslContext = createDefaultSSLContext();
        HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
        HttpsURLConnection connection = (HttpsURLConnection) new URL(url).openConnection();
        connection.setHostnameVerifier(createDefaultHostnameVerifier());
        return connection;
    }
}
