     */
    public byte[] deserializeData(String hexData) throws IOException {
        byte[] byteData = Hex.decodeHex(hexData.toCharArray());
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteData))) {
            return (byte[]) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException("Class not found during deserialization", e);
        }
    }
}
